(() => {
const card=document.querySelector('.lobbycard'),box=document.createElement('section');box.className='preflight';box.innerHTML='<strong>Antes de entrar</strong><p id="compatibilityStatus"></p><button id="prepareBeforeJoin" type="button">Preparar tradução neste dispositivo</button><p id="preflightStatus" role="status"></p>';card.append(box);
const voice=!!(window.SpeechRecognition||window.webkitSpeechRecognition),translation=!!window.Translator,media=!!navigator.mediaDevices?.getUserMedia;
document.getElementById('compatibilityStatus').textContent=!media?'Câmera e microfone indisponíveis neste navegador.':!translation?'Use Chrome no computador para as legendas traduzidas. Você ainda pode acompanhar os originais.':!voice&&!navigator.gpu?'Use texto digitado neste navegador.':'Chrome pronto para câmera, microfone e legendas.';
document.getElementById('prepareBeforeJoin').onclick=async()=>{const status=document.getElementById('preflightStatus'),button=document.getElementById('prepareBeforeJoin');button.disabled=true;try{if(!translation)throw Error('Use Chrome de desktop atualizado para tradução integrada.');const rid=new URLSearchParams(location.search).get('room');let source=document.getElementById('teacherLanguage').value,target=document.getElementById('targetLanguage').value;if(rid){const response=await fetch('/api/rooms/'+rid+'/info');if(!response.ok)throw Error('Não foi possível verificar a preparação da sala.');const info=await response.json();source=info.teacherLanguage||'pt';target=info.studentLanguage||'en'}status.textContent='Preparando tradução…';await getTranslator(source,target,true);await getTranslator(target,source,true);status.textContent='Pronto. A tradução desta aula está preparada.';}catch(error){status.textContent=error.message}finally{button.disabled=false}};
})();
